#[path="../owner_registry.rs"]mod owner_registry;
#[path="../owner_budget.rs"]mod owner_budget;
#[path="../journal.rs"]mod journal;
#[path="../owner.rs"]mod owner;
use std::alloc::{GlobalAlloc,Layout,System};use std::sync::atomic::{AtomicUsize,Ordering};use glam::DVec3;use ingetrazo_core::mesh::{Mesh,MeshVertex};
static CALLS:AtomicUsize=AtomicUsize::new(0);static BYTES:AtomicUsize=AtomicUsize::new(0);
struct Count;unsafe impl GlobalAlloc for Count{unsafe fn alloc(&self,l:Layout)->*mut u8{CALLS.fetch_add(1,Ordering::Relaxed);BYTES.fetch_add(l.size(),Ordering::Relaxed);System.alloc(l)}unsafe fn dealloc(&self,p:*mut u8,l:Layout){System.dealloc(p,l)}unsafe fn realloc(&self,p:*mut u8,l:Layout,n:usize)->*mut u8{CALLS.fetch_add(1,Ordering::Relaxed);BYTES.fetch_add(n,Ordering::Relaxed);System.realloc(p,l,n)}}#[global_allocator]static ALLOC:Count=Count;
fn main(){let mut rows=vec![];for n in [1usize,1000,50000]{let mut m=Mesh::new();m.vertices.reserve(n);for i in 0..n{m.vertices.push(MeshVertex::new(DVec3::new(i as f64,0.,0.)));}let o=owner::JournalOwner::new(m).unwrap();let before=o.registry_metrics();CALLS.store(0,Ordering::Relaxed);BYTES.store(0,Ordering::Relaxed);for _ in 0..1000{drop(o.try_begin().unwrap());}let calls=CALLS.load(Ordering::Relaxed);let bytes=BYTES.load(Ordering::Relaxed);let after=o.registry_metrics();assert_eq!((calls,bytes),(0,0));assert_eq!(before.cold_vertex_rows,after.cold_vertex_rows);assert_eq!(after.cold_vertex_rows,n);assert_eq!(after.lookup_calls,0);let warm_before=o.registry_metrics();if n>1{for i in 0..1000{let mut t=o.try_begin().unwrap();t.add_edge(DVec3::ZERO,DVec3::new((1+i%(n-1))as f64,0.,0.)).unwrap();drop(t);}}let warm_after=o.registry_metrics();assert_eq!(warm_before.cold_vertex_rows,warm_after.cold_vertex_rows);if n>1{assert_eq!(warm_after.lookup_calls-warm_before.lookup_calls,3000);}rows.push(serde_json::json!({"base_vertices":n,"begins":1000,"allocation_calls":calls,"allocated_bytes":bytes,"cold_vertex_rows":after.cold_vertex_rows,"lookup_calls":after.lookup_calls,"varying_operations":if n>1{1000}else{0},"varying_lookup_calls":warm_after.lookup_calls-warm_before.lookup_calls}));}println!("{}",serde_json::to_string_pretty(&rows).unwrap());}
